# The IDs aren't in strings directly (jevents compiled tables). Empirical approach: pin a busy loop and probe raw events 0x4000-0x40ff and 0x8000-0x80ff to see which count meaningfully. 
# But smarter: HiSilicon TaiShan v110 imp-def event numbers documented in mainline kernel? Actually mainline has tools/perf/pmu-events/arch/arm64/arm/cortex... and hisi json for hip08 uncore only.
# openEuler adds arm64/hisilicon/ core json. Let's fetch from Gitee openEuler kernel repo? Try local probe first.
cat > /tmp/spin.c << 'EOF'
#include <stdio.h>
volatile unsigned long x = 0;
int main(){ for (unsigned long i=0;i<200000000ULL;i++) x += i; return 0; }
EOF
gcc -O2 -o /tmp/spin /tmp/spin.c && echo built
taskset -c 0 perf stat -e cycles,instructions -x, /tmp/spin 2>&1 | head -3

# User is in wheel — can sudo with password. The kernel.bolt on: last resort test via su? We cannot provide password. Document honestly: uncore requires root or paranoid<=1.
# Verify the memory-latency behavior claim for core events: run a memory-bound workload and compare l1d vs l2d vs llc miss events
cat > /tmp/membench.c << 'EOF'
#include <stdlib.h>
int main(){ 
  size_t N = 1UL<<24; // 16M entries × 8B = 128MB, exceeds L3 partition per node
  unsigned long *a = malloc(N*8);
  for (size_t i=0;i<N;i++) a[i]=(i+1)%N;
  unsigned long p=0, s=0;
  for (int r=0;r<4;r++) { do { p=a[p]; s+=p; } while (p); }
  return s==1?0:0;
}
EOF
gcc -O2 -o /tmp/membench /tmp/membench.c && taskset -c 0 perf stat -e cycles,instructions,l1d_cache_refill,l2d_cache_refill,ll_cache_miss_rd,mem_stall_l2miss,remote_access_rd -- /tmp/membench 2>&1 | tail -12
